WITH recent_shipments AS (SELECT * FROM shipments WHERE cost > 79), cost_bucket_summary AS (SELECT CASE WHEN cost >= 84 THEN 'high' WHEN cost >= 38 THEN 'mid' ELSE 'low' END cost_bucket, SUM(CASE WHEN carrier = 'FedEx' THEN 1 ELSE 0 END) fedex_count, AVG(cost) avg_cost FROM recent_shipments GROUP BY CASE WHEN cost >= 84 THEN 'high' WHEN cost >= 38 THEN 'mid' ELSE 'low' END) SELECT * FROM cost_bucket_summary
